const c = ($('Clasificar (rúbrica 5 tareas)').first().json.message || {}).content || {};
const contactId = $('When Executed by Another Workflow').first().json.contactId;
const MAP = {'Boarding IA':'Internados','AA Familiar IA':'Intercambio académico con familias','Summer Camp IA':'Campamentos de verano','Pathway IA':'Pathway Alemania','Gap Year IA':'Gap Year / Estudia y Trabaja'};
const tags = Array.isArray(c.tags) ? c.tags : [];
const programa = tags.length ? (MAP[tags[0]] || null) : null;
return [{ json: { contactId, tipo: c.tipo || null, resumen: c.resumen || '', cualificado: String(c.cualificado || ''), programa } }];

const resp = $json.contact || $json;
const cfs = resp.customFields || [];
const cur = (cfs.find(f => f.id === 'xK2NFqtz1DYUw3gYdn8I') || {}).value;
const empty = !cur || (Array.isArray(cur) && !cur.length) || cur === '';
const programa = $('Preparar writes').first().json.programa;
const contactId = $('Preparar writes').first().json.contactId;
return [{ json: { should_set: !!(empty && programa), programa, contactId } }];

// Un solo resumen por contacto, que se actualiza (antes: una nota nueva por cada mensaje).  PRE-BSP-0923
const PREF = '🤖 Resumen del bot';
const notas = ($json.notes || []);
const previa = notas.find(n => String(n.body || '').startsWith(PREF));
const w = $('Preparar writes').first().json;
return [{ json: { contactId: w.contactId, noteId: previa ? previa.id : '', body: PREF + ' (se actualiza solo)\n\n' + (w.resumen || '') } }];
